import numpy as np, time
def ref(A):
    w,v=np.linalg.eig(A); i=np.argmax(np.abs(w)); return w[i],v[:,i]
def cand(A):
    w=np.linalg.eigvals(A); i=np.argmax(np.abs(w)); l=w[i]
    M=A-l*np.eye(A.shape[0]); u,s,vh=np.linalg.svd(M); return l, vh[-1].conj()
for size in [2,4,6,8,10]:
    for f,name in [(ref,'ref'),(cand,'cand')]:
        ts=[]
        for _ in range(200):
            A=np.random.normal(size=(size,size))
            t0=time.perf_counter(); f(A); ts.append(time.perf_counter()-t0)
        print(size,name,np.median(ts)*1e6)
"

