arguments.command:
cd /app && python -c "
import numpy as np, time
from scipy.linalg.lapack import dgeev
import scipy.linalg as sla
def ref(A):
    w,v=np.linalg.eig(A); i=np.argmax(np.abs(w)); return w[i],v[:,i]
def cand_lapack(A):
    wr,wi,vl,vr,info=dgeev(A,compute_vl=0,compute_vr=1,overwrite_a=1)
    mag=wr*wr+wi*wi; i=np.argmax(mag)
    if wi[i]==0:
        return wr[i], vr[:,i]
    if wi[i]>0:
        return complex(wr[i],wi[i]), vr[:,i]+1j*vr[:,i+1]
    return complex(wr[i],wi[i]), vr[:,i-1]-1j*vr[:,i]
def cand_scipy(A):
    w,v=sla.eig(A,check_finite=False,overwrite_a=True); i=np.argmax(np.abs(w)); return w[i],v[:,i]
for size in [2,4,6,8,10]:
    for f,name in [(ref,'ref'),(cand_lapack,'lapack'),(cand_scipy,'scipy')]:
        ts=[]
        for _ in range(300):
            A=np.random.normal(size=(size,size))
            t0=time.perf_counter(); f(A.copy()); ts.append(time.perf_counter()-t0)
        print(size,name,round(np.median(ts)*1e6,2))
"

